import json
with open('baseline-packages.json') as f: b = json.load(f)
with open('after-cpm-packages.json') as f: a = json.load(f)

def get_pkgs(data):
    result = {}
    for proj in data.get('projects', []):
        name = proj['path'].split('/')[-1]
        pkgs = {}
        for fw in proj.get('frameworks', []):
            for p in fw.get('topLevelPackages', []):
                pkgs[p['id']] = p.get('resolvedVersion', p.get('requestedVersion',''))
        result[name] = pkgs
    return result

bp, ap = get_pkgs(b), get_pkgs(a)
changes, unchanged = [], []
for proj in sorted(set(list(bp.keys()) + list(ap.keys()))):
    for pkg in sorted(set(list(bp.get(proj,{}).keys()) + list(ap.get(proj,{}).keys()))):
        bv = bp.get(proj,{}).get(pkg,'—')
        av = ap.get(proj,{}).get(pkg,'—')
        if bv != av:
            changes.append((proj, pkg, bv, av))
        else:
            unchanged.append((proj, pkg, bv))

print('=== CHANGES ===')
for c in changes: print(f'  {c[0]:20s} {c[1]:40s} {c[2]:>10s} -> {c[3]}')
if not changes: print('  None')
print(f'\n=== UNCHANGED ({len(unchanged)} entries) ===')
for u in unchanged[:3]: print(f'  {u[0]:20s} {u[1]:40s} {u[2]:>10s}')
if len(unchanged)>3: print(f'  ... and {len(unchanged)-3} more')
"

